import axios, { AxiosError, type AxiosResponse } from 'axios'
import { useSnackbar } from 'notistack'
import { useAuthHeader } from 'react-auth-kit'
import { useMutation, useQuery, useQueryClient } from 'react-query'

import { COMMON_MESSAGE } from 'src/data/messages'

import type {
  PartnerBenefitId,
  PartnerBenefitSnapshot,
  PartnerCoupon,
  PartnerCouponPayload,
  PartnerCouponStatus,
  PartnerCouponUnlockType,
  PartnerCouponUsageType,
  PartnerCouponWithStore,
  PartnerStore,
  PartnerStorePayload
} from 'src/models/partnerBenefit'

interface UsePartnerBenefitsOptions {
  mode?: 'user' | 'admin'
  isQueryEnabled?: boolean
}

interface StoreResDto {
  id: number
  name: string
  mapLink: string
  imageUrl?: string | null
  createdAt?: string
  updatedAt?: string
  deletedAt?: string | null
}

interface StoreImageResDto {
  url: string
}

interface StoreCouponResDto {
  id: number
  storeId?: number
  partnerStoreId?: number
  benefitContent: string
  startDate: string
  endDate: string
  audience: string
  howToUse: string
  verificationMethod: string
  notice: string
  usageType: PartnerCouponUsageType
  unlockType: PartnerCouponUnlockType
  status: PartnerCouponStatus
  createdAt?: string
  updatedAt?: string
  deletedAt?: string | null
}

interface StoreCouponUserStoreResDto {
  id: number
  name: string
  mapLink: string
  imageUrl?: string | null
}

interface StoreCouponUserResDto {
  id: number
  storeId?: number
  partnerStoreId?: number
  storeName?: string
  mapLink?: string
  imageUrl?: string | null
  benefitContent: string
  startDate: string
  endDate: string
  audience: string
  howToUse: string
  verificationMethod: string
  notice: string
  usageType: PartnerCouponUsageType
  unlockType: PartnerCouponUnlockType
  isLocked: boolean
  lockReason: PartnerCouponUnlockType | null
  store?: StoreCouponUserStoreResDto
}

interface UpdatePartnerStoreParams {
  storeId: PartnerBenefitId
  store: PartnerStorePayload
}

interface UploadPartnerStoreImageParams {
  storeId: PartnerBenefitId
  image: File
}

interface DeletePartnerStoreImageParams {
  storeId: PartnerBenefitId
}

interface UpdatePartnerCouponParams {
  couponId: PartnerBenefitId
  coupon: PartnerCouponPayload
}

interface DeletePartnerCouponParams {
  storeId: PartnerBenefitId
  couponId: PartnerBenefitId
}

const getAuthorizationHeader = (token: string) => ({ Authorization: token })

const getApiResponseData = <T>(responseData: T | { data: T }): T => {
  if (responseData && typeof responseData === 'object' && 'data' in responseData) {
    return responseData.data
  }

  return responseData
}

const getApiResponseArray = <T>(responseData: T[] | { data: T[] } | { content: T[] }): T[] => {
  if (Array.isArray(responseData)) return responseData
  if (responseData && typeof responseData === 'object' && 'data' in responseData && Array.isArray(responseData.data)) {
    return responseData.data
  }
  if (
    responseData &&
    typeof responseData === 'object' &&
    'content' in responseData &&
    Array.isArray(responseData.content)
  ) {
    return responseData.content
  }

  return []
}

const getApiErrorMessage = (error: unknown, fallbackMessage: string): string => {
  if (error instanceof AxiosError) return error.response?.data?.message ?? fallbackMessage
  if (error instanceof Error) return error.message
  return COMMON_MESSAGE.UNKNOWN_ERROR
}

const getPartnerStore = (store: StoreResDto | StoreCouponUserStoreResDto): PartnerStore => ({
  id: store.id,
  name: store.name,
  mapLink: store.mapLink,
  imageUrl: store.imageUrl ?? null,
  createdAt: 'createdAt' in store ? store.createdAt : undefined,
  updatedAt: 'updatedAt' in store ? store.updatedAt : undefined,
  deletedAt: 'deletedAt' in store ? store.deletedAt ?? null : null
})

const getPartnerCoupon = (coupon: StoreCouponResDto): PartnerCoupon => ({
  id: coupon.id,
  partnerStoreId: coupon.storeId ?? coupon.partnerStoreId ?? 0,
  benefitContent: coupon.benefitContent,
  startDate: coupon.startDate,
  endDate: coupon.endDate,
  audience: coupon.audience,
  howToUse: coupon.howToUse,
  verificationMethod: coupon.verificationMethod,
  notice: coupon.notice,
  usageType: coupon.usageType,
  unlockType: coupon.unlockType,
  status: coupon.status,
  createdAt: coupon.createdAt,
  updatedAt: coupon.updatedAt,
  deletedAt: coupon.deletedAt ?? null
})

const getUserPartnerCouponStore = (coupon: StoreCouponUserResDto): PartnerStore =>
  getPartnerStore(
    coupon.store ?? {
      id: coupon.storeId ?? coupon.partnerStoreId ?? 0,
      name: coupon.storeName ?? '',
      mapLink: coupon.mapLink ?? '',
      imageUrl: coupon.imageUrl ?? null
    }
  )

const getUserPartnerCouponItem = (coupon: StoreCouponUserResDto): PartnerCouponWithStore => {
  const store = getUserPartnerCouponStore(coupon)

  return {
    coupon: {
      id: coupon.id,
      partnerStoreId: store.id,
      benefitContent: coupon.benefitContent,
      startDate: coupon.startDate,
      endDate: coupon.endDate,
      audience: coupon.audience,
      howToUse: coupon.howToUse,
      verificationMethod: coupon.verificationMethod,
      notice: coupon.notice,
      usageType: coupon.usageType,
      unlockType: coupon.unlockType,
      status: 'ACTIVE',
      isLocked: coupon.isLocked,
      lockReason: coupon.lockReason,
      deletedAt: null
    },
    store
  }
}

const getStoreCouponRequestData = ({
  partnerStoreId: _partnerStoreId,
  ...coupon
}: PartnerCouponPayload): Omit<PartnerCouponPayload, 'partnerStoreId'> => coupon

const getUserPartnerBenefitSnapshot = async (token: string): Promise<PartnerBenefitSnapshot> => {
  const response = await axios.get<StoreCouponUserResDto[] | { data: StoreCouponUserResDto[] }>(
    `${process.env.REACT_APP_APIHOST}/store-coupons`,
    {
      headers: getAuthorizationHeader(token)
    }
  )
  const partnerCouponItems = getApiResponseArray(response.data).map(getUserPartnerCouponItem)
  const stores = Array.from(
    new Map(partnerCouponItems.map(partnerCouponItem => [partnerCouponItem.store.id, partnerCouponItem.store])).values()
  )

  return {
    stores,
    coupons: partnerCouponItems.map(partnerCouponItem => partnerCouponItem.coupon)
  }
}

const getUserPartnerCoupon = async (couponId: PartnerBenefitId, token: string): Promise<PartnerCouponWithStore> => {
  const response = await axios.get<StoreCouponUserResDto | { data: StoreCouponUserResDto }>(
    `${process.env.REACT_APP_APIHOST}/store-coupons/${couponId}`,
    {
      headers: getAuthorizationHeader(token)
    }
  )

  return getUserPartnerCouponItem(getApiResponseData(response.data))
}

const getAdminPartnerBenefitSnapshot = async (token: string): Promise<PartnerBenefitSnapshot> => {
  const storeResponse = await axios.get<StoreResDto[] | { data: StoreResDto[] }>(
    `${process.env.REACT_APP_APIHOST}/admin/stores`,
    {
      headers: getAuthorizationHeader(token)
    }
  )
  const stores = getApiResponseArray(storeResponse.data).map(getPartnerStore)
  const couponResponses = await Promise.all(
    stores.map(store =>
      axios.get<StoreCouponResDto[] | { data: StoreCouponResDto[] }>(
        `${process.env.REACT_APP_APIHOST}/admin/stores/${store.id}/coupons`,
        {
          headers: getAuthorizationHeader(token)
        }
      )
    )
  )

  return {
    stores,
    coupons: couponResponses.flatMap(response => getApiResponseArray(response.data).map(getPartnerCoupon))
  }
}

const createPartnerStoreApi = async (store: PartnerStorePayload, token: string): Promise<void> => {
  await axios.post<null, AxiosResponse<null>, PartnerStorePayload>(
    `${process.env.REACT_APP_APIHOST}/admin/stores`,
    store,
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const updatePartnerStoreApi = async ({ storeId, store }: UpdatePartnerStoreParams, token: string): Promise<void> => {
  await axios.patch<null, AxiosResponse<null>, PartnerStorePayload>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${storeId}`,
    store,
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const deletePartnerStoreApi = async (storeId: PartnerBenefitId, token: string): Promise<void> => {
  await axios.delete<null, AxiosResponse<null>, null>(`${process.env.REACT_APP_APIHOST}/admin/stores/${storeId}`, {
    headers: getAuthorizationHeader(token)
  })
}

const uploadPartnerStoreImageApi = async (
  { storeId, image }: UploadPartnerStoreImageParams,
  token: string
): Promise<StoreImageResDto> => {
  const formData = new FormData()
  formData.append('image', image)

  const response = await axios.post<StoreImageResDto>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${storeId}/image`,
    formData,
    {
      headers: getAuthorizationHeader(token)
    }
  )

  return response.data
}

const deletePartnerStoreImageApi = async ({ storeId }: DeletePartnerStoreImageParams, token: string): Promise<void> => {
  await axios.delete<null, AxiosResponse<null>, null>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${storeId}/image`,
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const createPartnerCouponApi = async (coupon: PartnerCouponPayload, token: string): Promise<void> => {
  await axios.post<null, AxiosResponse<null>, Omit<PartnerCouponPayload, 'partnerStoreId'>>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${coupon.partnerStoreId}/coupons`,
    getStoreCouponRequestData(coupon),
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const updatePartnerCouponApi = async (
  { couponId, coupon }: UpdatePartnerCouponParams,
  token: string
): Promise<void> => {
  await axios.patch<null, AxiosResponse<null>, Omit<PartnerCouponPayload, 'partnerStoreId'>>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${coupon.partnerStoreId}/coupons/${couponId}`,
    getStoreCouponRequestData(coupon),
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const deletePartnerCouponApi = async (
  { storeId, couponId }: DeletePartnerCouponParams,
  token: string
): Promise<void> => {
  await axios.delete<null, AxiosResponse<null>, null>(
    `${process.env.REACT_APP_APIHOST}/admin/stores/${storeId}/coupons/${couponId}`,
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

const useStoreCouponApi = async (couponId: PartnerBenefitId, token: string): Promise<void> => {
  await axios.post<null, AxiosResponse<null>, null>(
    `${process.env.REACT_APP_APIHOST}/store-coupons/${couponId}/use`,
    null,
    {
      headers: getAuthorizationHeader(token)
    }
  )
}

export const usePartnerCouponDetail = (couponId?: PartnerBenefitId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useQuery<PartnerCouponWithStore>(
    ['storeCoupon', couponId],
    () => getUserPartnerCoupon(couponId as PartnerBenefitId, token),
    {
      enabled: !!couponId && !!token,
      onError: error => {
        enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.SERVER_ERROR), { variant: 'error' })
      }
    }
  )
}

export const usePartnerBenefits = ({ mode = 'user', isQueryEnabled = true }: UsePartnerBenefitsOptions = {}) => {
  const { enqueueSnackbar } = useSnackbar()
  const queryClient = useQueryClient()
  const token = useAuthHeader()()
  const queryKey = mode === 'admin' ? ['adminPartnerBenefits'] : ['storeCoupons']
  const queryFn =
    mode === 'admin' ? () => getAdminPartnerBenefitSnapshot(token) : () => getUserPartnerBenefitSnapshot(token)
  const partnerBenefitQuery = useQuery<PartnerBenefitSnapshot>(queryKey, queryFn, {
    enabled: !!token && isQueryEnabled,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.SERVER_ERROR), { variant: 'error' })
    }
  })

  const invalidatePartnerBenefits = (): void => {
    queryClient.invalidateQueries(['adminPartnerBenefits'])
    queryClient.invalidateQueries(['storeCoupons'])
    queryClient.invalidateQueries(['storeCoupon'])
  }

  const createStoreMutation = useMutation((store: PartnerStorePayload) => createPartnerStoreApi(store, token), {
    onSuccess: invalidatePartnerBenefits,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.ADD_FAIL), { variant: 'error' })
    }
  })
  const updateStoreMutation = useMutation((params: UpdatePartnerStoreParams) => updatePartnerStoreApi(params, token), {
    onSuccess: invalidatePartnerBenefits,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.UPDATE_FAIL), { variant: 'error' })
    }
  })
  const deleteStoreMutation = useMutation((storeId: PartnerBenefitId) => deletePartnerStoreApi(storeId, token), {
    onSuccess: invalidatePartnerBenefits,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.DELETE_FAIL), { variant: 'error' })
    }
  })
  const uploadStoreImageMutation = useMutation(
    (params: UploadPartnerStoreImageParams) => uploadPartnerStoreImageApi(params, token),
    {
      onSuccess: invalidatePartnerBenefits,
      onError: error => {
        enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.UPDATE_FAIL), { variant: 'error' })
      }
    }
  )
  const deleteStoreImageMutation = useMutation(
    (params: DeletePartnerStoreImageParams) => deletePartnerStoreImageApi(params, token),
    {
      onSuccess: invalidatePartnerBenefits,
      onError: error => {
        enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.DELETE_FAIL), { variant: 'error' })
      }
    }
  )
  const createCouponMutation = useMutation((coupon: PartnerCouponPayload) => createPartnerCouponApi(coupon, token), {
    onSuccess: invalidatePartnerBenefits,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.ADD_FAIL), { variant: 'error' })
    }
  })
  const updateCouponMutation = useMutation(
    (params: UpdatePartnerCouponParams) => updatePartnerCouponApi(params, token),
    {
      onSuccess: invalidatePartnerBenefits,
      onError: error => {
        enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.UPDATE_FAIL), { variant: 'error' })
      }
    }
  )
  const deleteCouponMutation = useMutation(
    (params: DeletePartnerCouponParams) => deletePartnerCouponApi(params, token),
    {
      onSuccess: invalidatePartnerBenefits,
      onError: error => {
        enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.DELETE_FAIL), { variant: 'error' })
      }
    }
  )
  const useCouponMutation = useMutation((couponId: PartnerBenefitId) => useStoreCouponApi(couponId, token), {
    onSuccess: invalidatePartnerBenefits,
    onError: error => {
      enqueueSnackbar(getApiErrorMessage(error, COMMON_MESSAGE.UPDATE_FAIL), { variant: 'error' })
    }
  })

  return {
    stores: partnerBenefitQuery.data?.stores ?? [],
    coupons: partnerBenefitQuery.data?.coupons ?? [],
    isLoading: partnerBenefitQuery.isLoading,
    isFetching: partnerBenefitQuery.isFetching,
    isError: partnerBenefitQuery.isError,
    isEnabled: !!token,
    refreshPartnerBenefits: partnerBenefitQuery.refetch,
    createPartnerStore: (store: PartnerStorePayload) => createStoreMutation.mutateAsync(store),
    updatePartnerStore: (storeId: PartnerBenefitId, store: PartnerStorePayload) =>
      updateStoreMutation.mutateAsync({ storeId, store }),
    deletePartnerStore: (storeId: PartnerBenefitId) => deleteStoreMutation.mutateAsync(storeId),
    uploadPartnerStoreImage: (storeId: PartnerBenefitId, image: File) =>
      uploadStoreImageMutation.mutateAsync({ storeId, image }),
    deletePartnerStoreImage: (storeId: PartnerBenefitId) => deleteStoreImageMutation.mutateAsync({ storeId }),
    createPartnerCoupon: (coupon: PartnerCouponPayload) => createCouponMutation.mutateAsync(coupon),
    updatePartnerCoupon: (couponId: PartnerBenefitId, coupon: PartnerCouponPayload) =>
      updateCouponMutation.mutateAsync({ couponId, coupon }),
    deletePartnerCoupon: (storeId: PartnerBenefitId, couponId: PartnerBenefitId) =>
      deleteCouponMutation.mutateAsync({ storeId, couponId }),
    usePartnerCoupon: (couponId: PartnerBenefitId) => useCouponMutation.mutateAsync(couponId),
    isMutating:
      createStoreMutation.isLoading ||
      updateStoreMutation.isLoading ||
      deleteStoreMutation.isLoading ||
      uploadStoreImageMutation.isLoading ||
      deleteStoreImageMutation.isLoading ||
      createCouponMutation.isLoading ||
      updateCouponMutation.isLoading ||
      deleteCouponMutation.isLoading ||
      useCouponMutation.isLoading
  }
}
