import {
  PARTNER_BENEFIT_SEED_COUPONS,
  PARTNER_BENEFIT_SEED_STORES,
  PARTNER_COUPON_STORAGE_KEY,
  PARTNER_STORE_STORAGE_KEY
} from 'src/data/partnerBenefits'

import type {
  PartnerBenefitId,
  PartnerBenefitSnapshot,
  PartnerCoupon,
  PartnerCouponStatus,
  PartnerCouponUnlockType,
  PartnerCouponUsageType,
  PartnerCouponWithStore,
  PartnerStore
} from 'src/models/partnerBenefit'

type LocalStorageValue = Record<string, unknown>

const isStorageAvailable = (): boolean => typeof window !== 'undefined' && !!window.localStorage

const getCurrentIsoString = (): string => new Date().toISOString()

export const getDateInputValue = (date: Date = new Date()): string => {
  const year = date.getFullYear()
  const month = `${date.getMonth() + 1}`.padStart(2, '0')
  const day = `${date.getDate()}`.padStart(2, '0')

  return `${year}-${month}-${day}`
}

export const getDateInputValueFromString = (date: string): string => date.slice(0, 10)

export const formatPartnerBenefitDate = (date: string): string => getDateInputValueFromString(date).replaceAll('-', '.')

export const getStartOfDayIsoString = (date: string): string => `${date}T00:00:00.000Z`

export const getEndOfDayIsoString = (date: string): string => `${date}T23:59:59.999Z`

export const getIsPartnerCouponLocked = (coupon: Pick<PartnerCoupon, 'isLocked' | 'unlockType'>): boolean =>
  coupon.isLocked ?? coupon.unlockType === 'REVIEW_REQUIRED'

const parseStorageArray = <T>(storageKey: string): T[] | null => {
  if (!isStorageAvailable()) return null

  const storedValue = window.localStorage.getItem(storageKey)
  if (!storedValue) return null

  try {
    const parsedValue = JSON.parse(storedValue)
    return Array.isArray(parsedValue) ? parsedValue : null
  } catch (error) {
    return null
  }
}

const writeStorageArray = <T>(storageKey: string, values: T[]): void => {
  if (!isStorageAvailable()) return
  window.localStorage.setItem(storageKey, JSON.stringify(values))
}

const getTextValue = (value: unknown, fallback = ''): string => (typeof value === 'string' ? value : fallback)

const getNumberValue = (value: unknown, fallback: number): number => (typeof value === 'number' ? value : fallback)

const getDeletedAtValue = (value: unknown): string | null => (typeof value === 'string' ? value : null)

const getPartnerCouponUsageType = (value: unknown): PartnerCouponUsageType =>
  value === 'MULTI_USE' ? 'MULTI_USE' : 'ONE_TIME'

const getPartnerCouponUnlockType = (value: unknown): PartnerCouponUnlockType =>
  value === 'REVIEW_REQUIRED' ? 'REVIEW_REQUIRED' : 'INSTANT'

const getPartnerCouponStatus = (value: unknown): PartnerCouponStatus => (value === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE')

const getSemesterDateRange = (legacyCoupon: LocalStorageValue): Pick<PartnerCoupon, 'startDate' | 'endDate'> => {
  if (typeof legacyCoupon.startDate === 'string' && typeof legacyCoupon.endDate === 'string') {
    return { startDate: legacyCoupon.startDate, endDate: legacyCoupon.endDate }
  }

  const year = typeof legacyCoupon.year === 'number' ? legacyCoupon.year : 2026
  const semester = typeof legacyCoupon.semester === 'string' ? legacyCoupon.semester : ''
  const isFallSemester = semester.includes('SECOND') || semester.includes('FALL') || semester === '2'

  if (isFallSemester) {
    return {
      startDate: `${year}-09-01`,
      endDate: `${year + 1}-02-28`
    }
  }

  return {
    startDate: `${year}-03-01`,
    endDate: `${year}-08-31`
  }
}

const normalizePartnerStore = (store: LocalStorageValue, index: number): PartnerStore => {
  const now = getCurrentIsoString()

  return {
    id: getNumberValue(store.id, index + 1),
    name: getTextValue(store.name, `제휴 가게 ${index + 1}`),
    mapLink: getTextValue(store.mapLink ?? store.map_link, ''),
    imageUrl: getTextValue(store.imageUrl ?? store.image_url, ''),
    category: getTextValue(store.category, '기타'),
    locationLabel: getTextValue(store.locationLabel, ''),
    address: getTextValue(store.address, ''),
    createdAt: getTextValue(store.createdAt ?? store.created_at, now),
    updatedAt: getTextValue(store.updatedAt ?? store.updated_at, now),
    deletedAt: getDeletedAtValue(store.deletedAt ?? store.deleted_at)
  }
}

const normalizePartnerCoupon = (coupon: LocalStorageValue, index: number): PartnerCoupon => {
  const now = getCurrentIsoString()
  const { startDate, endDate } = getSemesterDateRange(coupon)

  return {
    id: getNumberValue(coupon.id, index + 1),
    partnerStoreId: getNumberValue(coupon.partnerStoreId ?? coupon.partner_store_id ?? coupon.storeId, 0),
    benefitContent: getTextValue(coupon.benefitContent ?? coupon.benefit_content ?? coupon.title, ''),
    startDate,
    endDate,
    audience: getTextValue(coupon.audience, ''),
    howToUse: getTextValue(coupon.howToUse ?? coupon.how_to_use, ''),
    verificationMethod: getTextValue(coupon.verificationMethod ?? coupon.verification_method, ''),
    notice: getTextValue(coupon.notice, ''),
    usageType: getPartnerCouponUsageType(coupon.usageType ?? coupon.usage_type),
    unlockType: getPartnerCouponUnlockType(coupon.unlockType ?? coupon.unlock_type),
    status: getPartnerCouponStatus(coupon.status),
    recommendedMenu: getTextValue(coupon.recommendedMenu ?? coupon.recommended_menu, ''),
    usageTime: getTextValue(coupon.usageTime ?? coupon.usage_time, ''),
    createdAt: getTextValue(coupon.createdAt ?? coupon.created_at, now),
    updatedAt: getTextValue(coupon.updatedAt ?? coupon.updated_at, now),
    deletedAt: getDeletedAtValue(coupon.deletedAt ?? coupon.deleted_at)
  }
}

const getNextId = <T extends { id: PartnerBenefitId }>(values: T[]): PartnerBenefitId =>
  values.reduce((maxId, value) => Math.max(maxId, value.id), 0) + 1

export const readPartnerBenefitSnapshot = (): PartnerBenefitSnapshot => {
  const storedStores = parseStorageArray<LocalStorageValue>(PARTNER_STORE_STORAGE_KEY)
  const storedCoupons = parseStorageArray<LocalStorageValue>(PARTNER_COUPON_STORAGE_KEY)

  if (!storedStores && !storedCoupons) {
    writeStorageArray(PARTNER_STORE_STORAGE_KEY, PARTNER_BENEFIT_SEED_STORES)
    writeStorageArray(PARTNER_COUPON_STORAGE_KEY, PARTNER_BENEFIT_SEED_COUPONS)

    return {
      stores: PARTNER_BENEFIT_SEED_STORES,
      coupons: PARTNER_BENEFIT_SEED_COUPONS
    }
  }

  const stores = (storedStores ?? []).map(normalizePartnerStore)
  const coupons = (storedCoupons ?? []).map(normalizePartnerCoupon)

  writeStorageArray(PARTNER_STORE_STORAGE_KEY, stores)
  writeStorageArray(PARTNER_COUPON_STORAGE_KEY, coupons)

  return { stores, coupons }
}

export const writePartnerBenefitSnapshot = ({ stores, coupons }: PartnerBenefitSnapshot): PartnerBenefitSnapshot => {
  writeStorageArray(PARTNER_STORE_STORAGE_KEY, stores)
  writeStorageArray(PARTNER_COUPON_STORAGE_KEY, coupons)

  return { stores, coupons }
}

export const getActivePartnerCouponItems = (
  snapshot: PartnerBenefitSnapshot,
  referenceDate: Date = new Date()
): PartnerCouponWithStore[] => {
  const currentDate = getDateInputValue(referenceDate)

  return snapshot.coupons
    .filter(coupon => {
      const store = snapshot.stores.find(store => store.id === coupon.partnerStoreId)
      return (
        !!store &&
        !store.deletedAt &&
        !coupon.deletedAt &&
        (coupon.status ?? 'ACTIVE') === 'ACTIVE' &&
        getDateInputValueFromString(coupon.startDate) <= currentDate &&
        currentDate <= getDateInputValueFromString(coupon.endDate)
      )
    })
    .map(coupon => ({
      coupon,
      store: snapshot.stores.find(store => store.id === coupon.partnerStoreId) as PartnerStore
    }))
}

export const getPartnerCouponItemById = (
  snapshot: PartnerBenefitSnapshot,
  couponId: PartnerBenefitId
): PartnerCouponWithStore | null => {
  const coupon = snapshot.coupons.find(coupon => coupon.id === couponId && !coupon.deletedAt)
  if (!coupon) return null

  const store = snapshot.stores.find(store => store.id === coupon.partnerStoreId && !store.deletedAt)
  if (!store) return null

  return { coupon, store }
}

export const createPartnerStore = (
  store: Omit<PartnerStore, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>
): PartnerStore => {
  const snapshot = readPartnerBenefitSnapshot()
  const now = getCurrentIsoString()
  const nextStore: PartnerStore = {
    ...store,
    id: getNextId(snapshot.stores),
    createdAt: now,
    updatedAt: now,
    deletedAt: null
  }

  writePartnerBenefitSnapshot({
    ...snapshot,
    stores: [...snapshot.stores, nextStore]
  })

  return nextStore
}

export const updatePartnerStore = (
  storeId: PartnerBenefitId,
  store: Omit<PartnerStore, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>
): PartnerStore | null => {
  const snapshot = readPartnerBenefitSnapshot()
  let updatedStore: PartnerStore | null = null

  const stores = snapshot.stores.map(currentStore => {
    if (currentStore.id !== storeId) return currentStore

    updatedStore = {
      ...currentStore,
      ...store,
      updatedAt: getCurrentIsoString()
    }

    return updatedStore
  })

  writePartnerBenefitSnapshot({ ...snapshot, stores })

  return updatedStore
}

export const deletePartnerStore = (storeId: PartnerBenefitId): PartnerBenefitSnapshot => {
  const snapshot = readPartnerBenefitSnapshot()
  const now = getCurrentIsoString()

  return writePartnerBenefitSnapshot({
    stores: snapshot.stores.map(store => (store.id === storeId ? { ...store, updatedAt: now, deletedAt: now } : store)),
    coupons: snapshot.coupons.map(coupon =>
      coupon.partnerStoreId === storeId ? { ...coupon, updatedAt: now, deletedAt: now } : coupon
    )
  })
}

export const createPartnerCoupon = (
  coupon: Omit<PartnerCoupon, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>
): PartnerCoupon => {
  const snapshot = readPartnerBenefitSnapshot()
  const now = getCurrentIsoString()
  const nextCoupon: PartnerCoupon = {
    ...coupon,
    id: getNextId(snapshot.coupons),
    createdAt: now,
    updatedAt: now,
    deletedAt: null
  }

  writePartnerBenefitSnapshot({
    ...snapshot,
    coupons: [...snapshot.coupons, nextCoupon]
  })

  return nextCoupon
}

export const updatePartnerCoupon = (
  couponId: PartnerBenefitId,
  coupon: Omit<PartnerCoupon, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>
): PartnerCoupon | null => {
  const snapshot = readPartnerBenefitSnapshot()
  let updatedCoupon: PartnerCoupon | null = null

  const coupons = snapshot.coupons.map(currentCoupon => {
    if (currentCoupon.id !== couponId) return currentCoupon

    updatedCoupon = {
      ...currentCoupon,
      ...coupon,
      updatedAt: getCurrentIsoString()
    }

    return updatedCoupon
  })

  writePartnerBenefitSnapshot({ ...snapshot, coupons })

  return updatedCoupon
}

export const deletePartnerCoupon = (couponId: PartnerBenefitId): PartnerBenefitSnapshot => {
  const snapshot = readPartnerBenefitSnapshot()
  const now = getCurrentIsoString()

  return writePartnerBenefitSnapshot({
    ...snapshot,
    coupons: snapshot.coupons.map(coupon =>
      coupon.id === couponId ? { ...coupon, updatedAt: now, deletedAt: now } : coupon
    )
  })
}
